# A guess must be from 1 to 100
def check_guess(guess):
    if guess < 1 or guess > 100:
        raise ValueError("guess must be from 1 to 100")
    return guess

for g in [50, 200]:
    try:
        print(check_guess(g))
    except ValueError as error:
        print("Refused:", error)

